import {esc,money,hours,today,addDays,monday,minutes,timeLabel,statusText,subjectClass,dateKey,statsFor,accountEntries} from './utils.js';
import {estimatedFee,attentionFor,plannedChanges,scheduleConflicts,reviewCategory} from './workflows.js';
import {buildStatement} from './statement.js';
const main=document.querySelector('#main'), dialog=document.querySelector('#dialog');
let state={students:[],courses:[],payments:[],reviews:[],periods:[],meta:{}}, loaded=false;
let route=location.hash.slice(1)||'schedule', anchor=today(), view='week', selectedStudent='', studentSearch='', studentStatus='active';
let filterStudent='',filterStatus='',statsMode='month',statsStart=today().slice(0,7)+'-01',statsEnd=today(),statsStudent='';
let studentAttention='',studentTab='overview',recordMode='recent',recordStart=addDays(today(),-30),recordEnd=today();
let reviewStudent='',reviewType='',reviewStatus='pending',reviewPage=0,agendaMode='today',showFilters=false;
let toastTimer;
const calendarPositions=new Map();
const studentBy=id=>state.students.find(s=>s.id===id);
const courseBy=id=>state.courses.find(c=>c.id===id);
const displayMinutes=c=>c.status==='completed'&&c.actual_minutes!=null?c.actual_minutes:c.duration_minutes;
const option=(value,label,selected)=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`;
const studentOptions=(selected,all=false)=>`${all?option('','所有学生',selected):''}${state.students.map(s=>option(s.id,s.name+(s.status!=='active'?`（${statusText(s.status)}）`:''),selected)).join('')}`;
const notice=(text,tone='')=>`<div class="notice ${tone}">${text}</div>`;
const empty=(text,action='')=>`<div class="empty"><p>${text}</p>${action}</div>`;
const button=(action,text,id='',cls='')=>`<button type="button" data-action="${action}" ${id?`data-id="${esc(id)}"`:''} class="${cls}">${text}</button>`;
const field=(label,control,cls='')=>`<label class="field ${cls}"><span>${label}</span>${control}</label>`;
const input=(name,type,value='',attrs='')=>`<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`;
const dateShort=d=>d?`${Number(d.slice(5,7))}月${Number(d.slice(8,10))}日`:'日期待核对';
const attentionLabels={debt:'已欠费',low:'不足下次课费',unverified:'余额待核对',normal:''};
const balanceHTML=s=>`<span class="${s.balance_cents<0?'negative':''}">${s.balance_cents<0?'欠费 '+money(-s.balance_cents):money(s.balance_cents)}</span>${!s.balance_verified?'<small class="unverified">已记录 · 待核对</small>':''}`;
const feeHTML=c=>c.status==='scheduled'?`预计 ${money(estimatedFee(c,studentBy(c.student_id)))}<small>尚未扣费</small>`:c.status==='cancelled'?'不扣费':money(c.fee_cents);
function toast(message,undo=null){const el=document.querySelector('#toast');el.replaceChildren(document.createTextNode(message));if(undo){const b=document.createElement('button');b.textContent='撤销本次记课';b.onclick=async()=>{b.disabled=true;try{await undo();toast('已撤销本次记课，余额已恢复');}catch(e){toast(e.message);}};el.append(b);}el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true;},undo?12000:4500);}
async function api(path,method='GET',body){let response;try{response=await fetch(`/api${path}`,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});}catch{throw new Error('无法连接本地服务，请确认课时簿仍在运行。');}let data;try{data=await response.json();}catch{throw new Error('本地服务返回了无法读取的内容，请稍后重试。');}if(!response.ok)throw new Error(data.error||'保存失败，请重试。');return data;}
async function refresh(){state=await api('/state');loaded=true;render();}
async function mutate(path,method,body,message='已保存'){const result=await api(path,method,body);await refresh();toast(message);return result;}
function openDialog(title,body,onSubmit,footer='保存',wide=false){
 if(dialog.open)dialog.close();dialog.classList.toggle('wide',wide);
 dialog.innerHTML=`<form><header class="dialog-head"><h2 id="dialog-title">${title}</h2><button type="button" data-close aria-label="关闭对话框" class="icon-button">×</button></header><div class="dialog-body">${body}<p class="form-error" role="alert" hidden></p></div><footer class="dialog-foot"><button type="button" data-close>${onSubmit?'取消':'关闭'}</button>${onSubmit?`<button type="submit" class="primary">${footer}</button>`:''}</footer></form>`;
 dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());dialog.showModal();
 dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const submit=e.submitter,error=dialog.querySelector('.form-error');error.hidden=true;if(submit)submit.disabled=true;try{const result=await onSubmit(Object.fromEntries(new FormData(e.target)));if(result!==false)dialog.close();}catch(err){error.textContent=err.message;error.hidden=false;}finally{if(submit)submit.disabled=false;}};
}
function confirmAction(title,content,action,label='确认'){openDialog(title,content,action,label);}
function header(_eyebrow,title,subtitle,actions=''){return `<header class="page-head"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${button('global-payment','＋ 记缴费')}${actions}</div></header>`;}
function render(){
 const calendar=main.querySelector('.calendar-scroll');if(calendar)calendarPositions.set(calendar.dataset.key,calendar.scrollTop);
 document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===route);if(a.dataset.nav===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 const count=document.querySelector('#review-count');count.textContent=state.reviews.filter(r=>r.status==='pending').length||'';
 if(!loaded)return;if(route==='students')renderStudents();else if(route==='stats')renderStats();else if(route==='settings')renderSettings();else if(route==='reviews')renderReviews();else renderSchedule();
}
function filteredCourses(){return state.courses.filter(c=>(!filterStudent||c.student_id===filterStudent)&&(!filterStatus||c.status===filterStatus));}
function agenda(){
 const now=new Date(), nowMinutes=now.getHours()*60+now.getMinutes();
 const pending=state.courses.filter(c=>c.status==='scheduled'&&c.date&&(c.date<today()||(c.date===today()&&c.start_time&&minutes(c.start_time)+c.duration_minutes<=nowMinutes)));
 const daily=state.courses.filter(c=>c.date===today()&&c.status!=='cancelled');
 const list=(agendaMode==='pending'?pending:daily).filter(c=>!filterStudent||c.student_id===filterStudent).sort((a,b)=>a.date.localeCompare(b.date)||(a.start_time||'').localeCompare(b.start_time||''));
 return `<section class="agenda" aria-label="今日工作台"><div class="agenda-heading"><div class="actions"><button data-action="agenda-today" class="text-button ${agendaMode==='today'?'current':''}">今日 ${daily.length} 节</button><button data-action="agenda-pending" class="text-button ${agendaMode==='pending'?'current':''}">待记课 ${pending.length}</button></div><small>${agendaMode==='pending'?'已过计划结束时间，请确认实际是否上课':dateShort(today())+' · 课后确认，按实际时长扣费'}</small></div><div class="agenda-list">${list.length?list.map(c=>`<article class="agenda-item ${c.status}"><div class="agenda-time">${agendaMode==='pending'?`<small>${dateShort(c.date)}</small>`:''}${c.start_time||'时间待核对'}</div><div class="agenda-person"><strong>${esc(studentBy(c.student_id)?.name)}</strong><span>${esc(c.subject)} · ${hours(displayMinutes(c))}</span></div><div class="agenda-fee">${feeHTML(c)}</div><div class="actions">${c.status==='scheduled'?button('complete-course','记课',c.id,'primary'): '<span class="done-label">✓ 已记课</span>'}${button('course','详情',c.id,'text-button')}</div></article>`).join(''):`<p class="agenda-empty">${agendaMode==='pending'?'没有待确认的课程。':'今天暂未排课，可点击下方空档安排。'}</p>`}</div></section>`;
}
function renderSchedule(){
 const start=monday(anchor),end=addDays(start,6),courses=filteredCourses();
 main.innerHTML=header('',view==='week'?'每周课表':'每月课表',view==='week'?`${dateShort(start)} — ${dateShort(end)}`:`${anchor.slice(0,4)} 年 ${Number(anchor.slice(5,7))} 月`,button('new-course','安排课程','','primary'))+
 agenda()+`<section class="planner"><div class="planner-toolbar"><div class="actions"><div class="segmented"><button data-action="view-week" aria-pressed="${view==='week'}">周</button><button data-action="view-month" aria-pressed="${view==='month'}">月</button></div><button data-action="prev" class="icon-button" aria-label="上一${view==='week'?'周':'月'}">‹</button><button data-action="today">今天</button><button data-action="next" class="icon-button" aria-label="下一${view==='week'?'周':'月'}">›</button><label class="sr-only" for="anchor">课表日期</label><input type="date" id="anchor" value="${anchor}"></div><div class="actions"><span class="legend-inline"><i class="done-swatch"></i> 已上课</span><button data-action="toggle-filters" aria-expanded="${showFilters}">筛选${filterStudent||filterStatus?' · 已启用':''}</button>${button('copy-week','复制上周')}</div></div><div class="planner-filters" ${showFilters?'':'hidden'}><label>学生 <select id="filter-student">${studentOptions(filterStudent,true)}</select></label><label>状态 <select id="filter-status">${option('','所有状态',filterStatus)}${['scheduled','completed','cancelled'].map(s=>option(s,statusText(s),filterStatus)).join('')}</select></label><span class="muted">点击空档排课 · 拖动待上课程调课</span></div>${view==='week'?weekGrid(start,courses):monthGrid(courses)}</section>`;
 bindSchedule();
 const scroll=main.querySelector('.calendar-scroll');if(scroll){
  const key=monday(anchor);scroll.dataset.key=key;scroll.style.maxHeight=Math.max(320,innerHeight-(scroll.getBoundingClientRect().top+scrollY)-24)+'px';
  const week=courses.filter(c=>c.date>=start&&c.date<=end&&c.start_time&&c.status!=='cancelled');
  const focus=week.filter(c=>c.date===today());const times=(focus.length?focus:week).map(c=>minutes(c.start_time));
  const earliest=Math.min(8,...courses.filter(c=>c.date>=start&&c.date<=end&&c.start_time).map(c=>Math.floor(minutes(c.start_time)/60)));
  scroll.scrollTop=calendarPositions.get(key)??Math.max(0,((times.length?Math.min(...times):9*60)-earliest*60-30)/60*64);
 }
}
function courseChip(c,style=''){const s=studentBy(c.student_id);return `<button class="course ${subjectClass(c.subject)} ${c.status} ${c.conflict?'conflict':''}" data-action="${c.status==='scheduled'?'complete-course':'course'}" data-id="${esc(c.id)}" ${style?`style="${style}"`:''} draggable="${c.status==='scheduled'}" title="${esc(`${s?.name} · ${c.subject} · ${c.start_time||'时间待核对'} · ${statusText(c.status)}`)}"><span class="course-top"><strong>${esc(s?.name||'未知学生')}</strong><span class="subject-dot"></span></span><span>${esc(c.subject)} <span class="course-time">${c.start_time||'时间待核对'}${c.start_time?`–${timeLabel(minutes(c.start_time)+displayMinutes(c))}`:''}</span></span><small>${c.status==='completed'?`✓ 已上课 · ${hours(c.actual_minutes)}`:c.status==='cancelled'?'请假 / 取消':hours(c.duration_minutes)}${c.needs_review?' · 待核对':''}${c.conflict?' · 时间冲突':''}</small></button>`;}
function bindSchedule(){
 document.querySelector('#anchor').onchange=e=>{anchor=e.target.value||today();render();};
 document.querySelector('#filter-student').onchange=e=>{filterStudent=e.target.value;render();};document.querySelector('#filter-status').onchange=e=>{filterStatus=e.target.value;render();};
 main.querySelectorAll('.course[draggable="true"]').forEach(el=>el.ondragstart=e=>{e.dataTransfer.setData('text/plain',el.dataset.id);e.dataTransfer.effectAllowed='move';});
 main.querySelectorAll('[data-date]').forEach(el=>{el.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move';};el.ondrop=e=>{e.preventDefault();e.stopPropagation();const c=courseBy(e.dataTransfer.getData('text/plain'));if(c?.status==='scheduled')courseForm(c,{date:el.dataset.date,start_time:el.dataset.time||c.start_time});};});
}
function studentPicker(selected){return field('搜索学生',input('student_query','search','','placeholder="姓名或年级" autocomplete="off"'))+field('学生',`<select name="student_id" required>${studentOptions(selected)}</select>`);}
function bindStudentPicker(onChange=()=>{}){
 const query=dialog.querySelector('[name="student_query"]'),select=dialog.querySelector('[name="student_id"]');if(!query)return;
 query.oninput=()=>{const current=select.value;select.innerHTML=state.students.filter(s=>(s.name+' '+s.grade).includes(query.value.trim())).map(s=>option(s.id,s.name,current)).join('');onChange(select.value);};select.onchange=()=>onChange(select.value);
}
function courseForm(c=null,defaults={}){
 if(!state.students.length){studentForm();return;}
 const item={student_id:filterStudent||selectedStudent||state.students.find(s=>s.status==='active')?.id||state.students[0].id,date:anchor,start_time:'18:00',duration_minutes:120,notes:'',...c,...defaults};
 const subjects=[...new Set([...Object.keys(studentBy(item.student_id)?.rates||{}),...(c?.source?['数学','物理',c.subject]:[])])];item.subject=item.subject||subjects[0];
 const historical=!!c?.source;
 openDialog(c?'编辑课程':'安排课程',`<div class="form-grid">${c?field('学生',`<strong>${esc(studentBy(c.student_id)?.name)}</strong>`):studentPicker(item.student_id)}${field('科目',`<select name="subject" ${c&&!historical?'disabled':''}>${subjects.map(s=>option(s,s,item.subject)).join('')}</select>`)}${field(historical?'日期（未知可留空）':'日期',input('date','date',item.date,historical?'':'required'))}${field(historical?'开始时间（未知可留空）':'开始时间',input('start_time','time',item.start_time,`${historical?'':'required'} step="60"`))}${field('计划时长（小时）',input('duration_hours','number',item.duration_minutes/60,`required min="${historical?'0.01':'1'}" max="24" step="${historical?'any':'1'}"`))}${!c?field('每周重复至（可不填）',input('repeat_until','date','','min="'+item.date+'"')):''}${c?.series_id&&c.status==='scheduled'?field('修改范围',`<select name="scope">${option('one','仅本次','one')}${option('following','本次及以后待上课程','one')}</select>`):''}${field('备注',`<textarea name="notes" rows="2">${esc(item.notes)}</textarea>`,'full')}${c?.needs_review?field('核对已填写的信息','<span class="check"><input type="checkbox" name="reviewed">确认本次补充；仍缺失的事项继续保留</span>','full'):''}</div><div id="schedule-preview" aria-live="polite"></div>${historical?`<details><summary>原始来源</summary><p class="source">${esc(c.source)}</p></details>`:''}`,async f=>{
  const changes=plannedChanges(state.courses,c,f),conflicts=scheduleConflicts(state.courses,changes);
  if(conflicts.length&&!f.overlap_ack)throw new Error('此安排存在时间重叠，请查看下方冲突并确认继续。');
  const payload={date:f.date||null,start_time:f.start_time||null,duration_minutes:Math.round(Number(f.duration_hours)*60),notes:f.notes};
  if(c){payload.scope=f.scope||'one';if(historical)payload.subject=f.subject;if(f.reviewed)payload.needs_review=false;await mutate(`/courses/${c.id}`,'PATCH',payload);}
  else{payload.student_id=f.student_id;payload.subject=f.subject;if(f.repeat_until)payload.repeat_until=f.repeat_until;await mutate('/courses','POST',payload,'课程已安排');}
 });
 const preview=()=>{const f=Object.fromEntries(new FormData(dialog.querySelector('form'))),changes=plannedChanges(state.courses,c,f),conflicts=scheduleConflicts(state.courses,changes);dialog.querySelector('#schedule-preview').innerHTML=`${changes.length>1?notice(`将${c?'修改':'安排'} ${changes.length} 节课：${changes.slice(0,4).map(x=>dateShort(x.date)).join('、')}${changes.length>4?'等':''}。已完成课程保持原记录。`):''}${conflicts.length?notice(`<strong>有 ${conflicts.length} 处时间重叠</strong><ul>${conflicts.slice(0,5).map(({change,other})=>`<li>${dateShort(change.date)} ${change.start_time} 与 ${esc(studentBy(other.student_id)?.name)} ${other.start_time}–${timeLabel(minutes(other.start_time)+displayMinutes(other))} 重叠</li>`).join('')}</ul><label class="check"><input type="checkbox" name="overlap_ack">已知晓重叠，仍按此安排</label>`,'warning'):''}`;};
 dialog.querySelectorAll('[name="date"],[name="start_time"],[name="duration_hours"],[name="repeat_until"],[name="scope"]').forEach(x=>x.addEventListener('input',preview));
 if(!c)bindStudentPicker(id=>{const select=dialog.querySelector('[name="subject"]');select.innerHTML=Object.keys(studentBy(id)?.rates||{}).map(s=>option(s,s,select.value)).join('');preview();});preview();
}
function courseDetail(c){
 const s=studentBy(c.student_id);
 openDialog(`${esc(s?.name||'未知学生')} · ${esc(c.subject)}`,`<p class="detail-lead">${dateShort(c.date)} ${c.start_time||'时间待核对'}</p><dl class="key-values"><div><dt>状态</dt><dd>${statusText(c.status)}</dd></div><div><dt>计划课时</dt><dd>${hours(c.duration_minutes)}</dd></div><div><dt>实际课时</dt><dd>${c.status==='completed'?hours(c.actual_minutes):'—'}</dd></div><div><dt>${c.status==='scheduled'?'预计课费':'本次课费'}</dt><dd>${feeHTML(c)}</dd></div><div><dt>${s.balance_verified?'当前余额':'当前已记录余额'}</dt><dd>${balanceHTML(s)}</dd></div></dl>${c.conflict?notice('与其他课程时间重叠，请检查排期。','warning'):''}${c.needs_review?notice('历史信息尚未核对完整，待核对费用未计入确定账目。'):''}${c.notes?`<p class="preserve">${esc(c.notes)}</p>`:''}${c.source?`<details><summary>原始来源</summary><p class="source">${esc(c.source)}</p></details>`:''}<div class="dialog-actions">${c.status==='scheduled'?button('complete-course','记课并扣费',c.id,'primary'):c.status==='completed'?button('correct-course','更正课时 / 费用',c.id):button('reschedule-course','恢复为待上课',c.id)}${button('edit-course','调整时间 / 备注',c.id)}${button('payment','记缴费',s.id)}${button('open-student','学生账页',s.id)}</div><div class="dialog-actions">${c.status==='scheduled'?button('cancel-course','请假 / 取消',c.id)+(!c.source?button('delete-course','删除排课',c.id,'text-button danger'):''):c.status==='completed'?button('undo-course','撤销已上课',c.id,'text-button'):''}</div>`,null);
}
function completeForm(c,correct=false){
 const s=studentBy(c.student_id),rate=correct?c.hourly_rate_cents:s?.rates?.[c.subject];
 openDialog(correct?'更正已完成课程':'记课并扣费',`<p class="detail-lead">${esc(s?.name)} · ${esc(c.subject)} <small>${dateShort(c.date)} ${c.start_time||''}</small></p>${!correct?button('course','课程详情 / 调课',c.id,'text-button'):''}<div class="form-grid">${field('实际时长（小时）',input('actual_hours','number',(c.actual_minutes??c.duration_minutes)/60,`required min="${c.source?'0.01':'1'}" max="24" step="${c.source?'any':'1'}"`))}${field('本次小时价（元）',input('rate','number',rate==null?'':rate/100,`required min="0" step="0.01" ${correct?'':'readonly'}`))}${field('备注',`<textarea name="notes" rows="2">${esc(c.notes)}</textarea>`,'full')}</div>${c.source?`<details ${c.needs_review?'open':''}><summary>历史课程信息</summary><div class="form-grid">${field('日期（未知可留空）',input('date','date',c.date))}${field('开始时间（未知可留空）',input('start_time','time',c.start_time))}${field('科目',input('subject','text',c.subject,'required'))}</div><p class="source">${esc(c.source)}</p></details>`:''}<div id="completion-preview" class="completion-preview" aria-live="polite"></div>${!s?.balance_verified?notice('当前余额尚未核实，预览只反映已记录账目。'):''}${rate==null&&!correct?notice('该科目尚未设置单价，请先编辑学生档案。 '+button('edit-student','设置单价',s.id),'warning'):''}${c.needs_review?field('核对确认','<span class="check"><input type="checkbox" name="reviewed" required>已确认本次填写的时长和单价；未补齐的历史信息继续待核对</span>'):''}`,async f=>{
  const payload={status:'completed',actual_minutes:Math.round(Number(f.actual_hours)*60),notes:f.notes};if(correct)payload.hourly_rate_cents=Math.round(Number(f.rate)*100);
  if(c.source)Object.assign(payload,{date:f.date||null,start_time:f.start_time||null,subject:f.subject});if(c.needs_review&&f.reviewed)payload.needs_review=false;
  const result=await api(`/courses/${c.id}`,'PATCH',payload);await refresh();
  if(correct){toast(result.needs_review?'已保存，仍有历史信息待核对':'已更正，余额已重新计算');return;}
  const after=studentBy(s.id);toast(`${s.name} · 已记 ${hours(payload.actual_minutes)}，${after.balance_cents<0?'欠费 '+money(-after.balance_cents):'余额 '+money(after.balance_cents)}`,async()=>{await api(`/courses/${c.id}`,'PATCH',{status:'scheduled',actual_minutes:c.actual_minutes,hourly_rate_cents:c.hourly_rate_cents});await refresh();});
 },correct?'保存更正':'确认扣费');
 const preview=()=>{const h=Number(dialog.querySelector('[name="actual_hours"]').value),rateValue=dialog.querySelector('[name="rate"]').value,r=Number(rateValue),cost=rateValue===''?null:Math.round(h*r*100),balance=cost==null?null:s.balance_cents+(correct?(c.fee_cents||0):0)-cost;dialog.querySelector('#completion-preview').innerHTML=`<span>${h} 小时 × ${money(rateValue===''?null:Math.round(r*100))}</span><strong>${correct?'更正后课费':'本次扣费'} ${money(cost)}</strong><span>${correct?'更正后':'扣费后'}${s.balance_verified?'余额':'已记录余额'} <b class="${balance<0?'negative':''}">${balance<0?'欠费 '+money(-balance):money(balance)}</b></span>${correct&&c.fee_cents!=null&&cost!=null?`<span>原扣费 ${money(c.fee_cents)} · ${cost<c.fee_cents?'退回余额':'补扣'} ${money(Math.abs(cost-c.fee_cents))}</span>`:''}`;};
 dialog.querySelectorAll('input').forEach(i=>i.addEventListener('input',preview));preview();if(rate==null&&!correct)dialog.querySelector('[type="submit"]').disabled=true;
}
function rangeControls(){return `<div class="record-controls"><label>记录范围 <select id="record-mode">${option('recent','近 30 天',recordMode)}${option('all','全部记录',recordMode)}${state.periods.map(p=>option('period:'+p.id,p.name,recordMode)).join('')}${option('custom','自定义',recordMode)}</select></label>${recordMode!=='all'?`<label>从 <input id="record-start" type="date" value="${recordStart}"></label><label>至 <input id="record-end" type="date" value="${recordEnd}"></label>`:''}</div>`;}
const inRecordRange=e=>recordMode==='all'||(e.date&&e.date>=recordStart&&e.date<=recordEnd);
