 if(!students.some(s=>s.id===selectedStudent))selectedStudent=students[0]?.id||'';
 main.innerHTML=header('','学生账页',`${students.length} 位学生 · 查看余额、课程与往来`,button('new-student','添加学生','','primary'))+`<div class="attention-filters"><button data-action="attention" data-id="" aria-pressed="${!studentAttention}">全部</button>${['debt','low','unverified'].map(k=>`<button data-action="attention" data-id="${k}" aria-pressed="${studentAttention===k}">${attentionLabels[k]} <b>${state.students.filter(s=>(!studentStatus||s.status===studentStatus)&&(!studentSearch||(s.name+' '+s.grade).includes(studentSearch))&&attentionFor(s,state.courses)===k).length}</b></button>`).join('')}</div><div class="students-layout"><section class="student-index"><div class="student-controls"><label class="sr-only" for="student-search">搜索姓名或年级</label><input id="student-search" type="search" placeholder="搜索姓名或年级" value="${esc(studentSearch)}"><label class="sr-only" for="student-status">学生状态</label><select id="student-status">${option('','全部状态',studentStatus)}${['active','paused','archived'].map(s=>option(s,statusText(s),studentStatus)).join('')}</select></div><div class="student-list">${students.map(s=>`<button class="student-row ${s.id===selectedStudent?'selected':''}" data-action="select-student" data-id="${esc(s.id)}"><span><strong>${esc(s.name)}</strong><small>${esc(s.grade||'未填年级')} · ${statusText(s.status)}</small></span><span class="student-balance">${balanceHTML(s)}${attentionFor(s,state.courses)==='low'?'<small class="negative">不足下次课费</small>':''}</span></button>`).join('')||empty('没有符合条件的学生。')}</div></section><section class="student-detail">${selectedStudent?studentDetail(studentBy(selectedStudent)):empty('添加学生后即可安排课程、记缴费。')}</section></div>`;
