 if(blocked.length){openDialog('先核对影响余额的课程',`<p>${esc(s.name)} 有 <strong>${blocked.length} 节已上课</strong> 的费用尚未确定，补齐后才能确认余额。</p>${notice('当前已记录余额不能代表实际余额。请补充已知信息；未知日期、时长和价格继续保留，不需要猜填。')}<div class="blocking-list">${blocked.slice(0,12).map(c=>`<div><span>${dateShort(c.date)} · ${esc(c.subject)}</span>${button('correct-course','核对这节课',c.id)}</div>`).join('')}</div>${button('student-reviews','查看全部核对事项',s.id)}`,null);return;}
